class Task {
  constructor(title) {
    this.title = title;
  }

  describe() {
    return `${this.title}`;
  }
}
console.log(new Task("Ship Hypershell").describe());

void (async () => {
  const values = await Promise.all([Promise.resolve(1), Promise.resolve(2)]);
  console.log(values);
})();

try {
  const result = JSON.parse("not json");
  console.log(result);
} catch (error) {
  console.error(`Unable to complete operation: ${error.message}`);
}

const values = [12, 3, 42];
values.sort((a, b) => a - b);
console.log(values);

for (const [key, value] of Object.entries({ answer: 42 })) {
  console.log(key, value);
}

const values = new Map();
values.set("answer", 42);
console.log(values.get("answer"));

const values = new Set([12, 7]);
values.add(42);
console.log([...values]);

void (async () => {
  const outcomes = await Promise.allSettled([Promise.resolve(42), Promise.reject(new Error("nope"))]);
  console.log(outcomes.map((outcome) => outcome.status));
})();

void (async () => {
  const result = await Promise.race([Promise.resolve(42), new Promise((resolve) => setTimeout(() => resolve(7), 10))]);
  console.log(result);
})();

async function main() {
  console.log(await Promise.resolve(42));
}
void main();
